	}
	return stats
}"},{"rank":3,"score":103.9884,"file_path":"internal/cli/history_vec.go","start_line":370,"end_line":372,"focus_line":370,"snippet_start_line":370,"snippet_end_line":372,"symbol_start_line":370,"symbol_end_line":372,"language":"Go","kind":"function","symbol_id":"gh/entireio/entire-brain:Go:internal/cli/history_vec.go:function:conversationVectorModelID","symbol_name":"conversationVectorModelID","qualified_name":"conversationVectorModelID","signature":"func conversationVectorModelID(modelID string) string","signals":["graph:calls","graph:outgoing","graph:callers"],"snippet":"func conversationVectorModelID(modelID string) string {
