type memoryClock func() time.Time

func fixedMemoryClock(now time.Time) memoryClock {
	return func() time.Time { return now }
}

func memoryClockNow(clock memoryClock) time.Time {
	if clock == nil {
		return time.Now().UTC()
	}
	return clock().UTC()
}

