	if len(issues) == 0 {
		return nil
	}
	// Error() reports Issues[0], and the issues arrive in directory-read order,
	// which is creation-ordered on APFS but hash-ordered on ext4. The same
	// damaged Brain therefore produced different text on different machines.
	// Sort a copy (the caller's slice keeps its discovery order) most severe
	// first, tie-broken by kind and file so the message is fully determined by
	// the state on disk.
	ordered := append([]memoryStateIssue(nil), issues...)
	sort.SliceStable(ordered, func(i, j int) bool {
		ri, rj := memoryStateSeverityRank(ordered[i].Code), memoryStateSeverityRank(ordered[j].Code)
		if ri != rj {
			return ri < rj
		}
		if ordered[i].Kind != ordered[j].Kind {
			return ordered[i].Kind < ordered[j].Kind
		}
		return ordered[i].File < ordered[j].File
	})
	return &memoryStateLoadError{Issues: ordered}
}"},{"rank":4,"score":110.5086,"file_path":"internal/cli/memory_cmd.go","start_line":408,"end_line":487,"focus_line":408,"snippet_start_line":408,"snippet_end_line":413,"symbol_start_line":408,"symbol_end_line":658,"language":"Go","kind":"function","symbol_id":"gh/entireio/entire-brain:Go:internal/cli/memory_cmd.go:function:reconcileMemoryJobsLockedDetailed","symbol_name":"reconcileMemoryJobsLockedDetailed","qualified_name":"reconcileMemoryJobsLockedDetailed","signature":"func reconcileMemoryJobsLockedDetailed(brainDir, trigger string, now time.Time, snapshot *memoryReconcileSnapshot, dryRun bool, receipt *memoryOperationReceipt) (created int, err error)","signals":["body","exact-symbol","symbol-name","signature","exact-code-token","graph:callers"],"snippet":"func reconcileMemoryJobsLockedDetailed(brainDir, trigger string, now time.Time, snapshot *memoryReconcileSnapshot, dryRun bool, receipt *memoryOperationReceipt) (created int, err error) {
