	ticker := time.NewTicker(memoryAbstractCancellationPollInterval)
	defer ticker.Stop()
	var runErr error
	var deterministicErr error
	waiting := true
	for waiting {
		select {
		case runErr = <-runDone:
			waiting = false
		case <-ticker.C:
			request, cancelErr := loadMemoryCancellationRequest(brainDir, claimed.JobID)
			if cancelErr != nil {
				deterministicErr = cancelErr
				cancelProvider()
				runErr = <-runDone
				waiting = false
				continue
			}
			if request != nil {
				cancelProvider()
				runErr = <-runDone
				waiting = false
				continue
			}
			if err := runDeterministicPass(); err != nil {
				deterministicErr = err
				cancelProvider()
				runErr = <-runDone
				waiting = false
			}
		case <-ctx.Done():
