// workspaceCommandFixture deliberately uses the same on-disk member corpus and
// workspace manifest paths as the root command.  The test providers are native
// local binaries (fakeCodexProvider), and HOME/XDG are isolated so no command
// can discover or write a user's provider or skill configuration.
func workspaceCommandFixture(t *testing.T) (Options, EntireEnv, workspaceManifest) {
	t.Helper()
	isolateSkillFormHome(t)
	env, manifest := twoRepoWorkspace(t,
		"gh/acme/a", "release:build", []string{"mise build", "mise deploy"},
		"gh/acme/b", "release:ship", []string{"make build", "make release"})
	if err := writeWorkspaceManifest(env, manifest); err != nil {
		t.Fatal(err)
	}
	return Options{
		Version: "test", Env: env,
		Runner: &fakeCommandRunner{responses: map[string]fakeCommandResponse{}},
		Now:    func() time.Time { return time.Date(2026, 9, 18, 12, 0, 0, 0, time.UTC) },
	}, env, manifest
}

func workspaceSkillInstallPath(t *testing.T) string {
	t.Helper()
	home, err := os.UserHomeDir()
	if err != nil {
		t.Fatal(err)
	}
	return filepath.Join(home, ".agents", "skills", "deploy-release", "SKILL.md")
}

func assertWorkspaceSkillNotWritten(t *testing.T, wsDir string) {
	t.Helper()
	for _, path := range []string{workspaceSkillInstallPath(t), filepath.Join(wsDir, filepath.FromSlash(patternsSkillMemoryPath))} {
		if _, err := os.Stat(path); !os.IsNotExist(err) {
			t.Fatalf("workspace form wrote %s: %v", path, err)
		}
	}
}

func TestWorkspaceCommandLifecycleThroughRootRoutes(t *testing.T) {
	opts, _, manifest := workspaceCommandFixture(t)

	// Refresh is the live legacy-view bridge consumed by the subsequent list and
	// status routes.  Exercise text output first, then JSON filtering and limits.
	out, err := execute(t, NewRootCommand(opts), "workspace", "patterns", "refresh", manifest.Name)
	if err != nil || !strings.Contains(out, "cross-repo V2 pattern") {
		t.Fatalf("refresh: %v\n%s", err, out)
	}
	out, err = execute(t, NewRootCommand(opts), "workspace", "patterns", manifest.Name, "--scope", "workspace", "--type", "task", "--limit", "1", "--json")
	if err != nil {
		t.Fatalf("filtered list: %v\n%s", err, out)
	}
	var views []patternView
	if err := json.Unmarshal([]byte(out), &views); err != nil || len(views) != 1 || views[0].Scope != "workspace" || views[0].Type != "task" {
		t.Fatalf("filtered list = %#v, decode=%v\n%s", views, err, out)
	}
	out, err = execute(t, NewRootCommand(opts), "workspace", "patterns", "status", manifest.Name)
	if err != nil || !strings.Contains(out, "member repos: 2 (0 with patterns)") || !strings.Contains(out, "cross-repo V2 patterns: 2") {
		t.Fatalf("status: %v\n%s", err, out)
	}
	// Until an explicit verifier run, the skills list must not expose raw task
	// candidates as formable workspace skills.
	out, err = execute(t, NewRootCommand(opts), "workspace", "patterns", "skills", manifest.Name)
	if err != nil || !strings.Contains(out, "no accepted cross-repo families") {
		t.Fatalf("unverified skills list: %v\n%s", err, out)
	}

	// Verification is egress-gated in production.  A portable, native fake
	// provider gives the root command a deterministic accepted family instead.
	family := `{"families":[{"title":"release the build","trigger":"shipping a release","purpose":"build then publish","common_workflow":["build","publish"],"per_repo":[{"repo_key":"gh/acme/a","commands":["mise build","mise deploy"]},{"repo_key":"gh/acme/b","commands":["make build","make release"]}],"verdict":"accepted"}]}`
	fakeCodexProvider(t, family)
	out, err = execute(t, NewRootCommand(opts), "workspace", "patterns", "verify", manifest.Name, "--agent", "codex", "--json")
	if err != nil || !strings.Contains(out, `"Verified": 1`) {
		t.Fatalf("verify: %v\n%s", err, out)
	}
	// A second root-route verification has unchanged evidence and must take the
	// cached path. Replacing the provider with invalid output proves the command
	// did not execute it while evidence is unchanged.
	fakeCodexProvider(t, "not JSON")
	out, err = execute(t, NewRootCommand(opts), "workspace", "patterns", "verify", manifest.Name, "--agent", "codex", "--json")
	if err != nil || !strings.Contains(out, `"Cached": 1`) {
		t.Fatalf("cached verify: %v\n%s", err, out)
	}
	out, err = execute(t, NewRootCommand(opts), "workspace", "patterns", "skills", manifest.Name, "--limit", "1")
	if err != nil || !strings.Contains(out, "[family] release the build") || !strings.Contains(out, "gh/acme/a, gh/acme/b") {
		t.Fatalf("skills text list: %v\n%s", err, out)
	}

	out, err = execute(t, NewRootCommand(opts), "workspace", "patterns", "skills", manifest.Name, "--limit", "1", "--json")
	if err != nil {
		t.Fatalf("skills list: %v\n%s", err, out)
	}
	var families []workspaceFamily
	if err := json.Unmarshal([]byte(out), &families); err != nil || len(families) != 1 || families[0].repoCount() != 2 {
		t.Fatalf("skills list = %#v, decode=%v\n%s", families, err, out)
	}

	fakeCodexProvider(t, regressionSkill)
	out, err = execute(t, NewRootCommand(opts), "workspace", "patterns", "skills", "form", manifest.Name, families[0].ID, "--agent", "codex", "--json")
	if err != nil || !strings.Contains(out, `"would_write"`) || !strings.Contains(out, `"name": "deploy-release"`) {
		t.Fatalf("preview form: %v\n%s", err, out)
	}
	wsDir, err := workspaceDir(opts.Env, manifest.Name)
	if err != nil {
		t.Fatal(err)
	}
	assertWorkspaceSkillNotWritten(t, wsDir)
	// draft-only is also read-only, while --yes reaches the actual global
	// workspace destination and records the workspace decision.
	out, err = execute(t, NewRootCommand(opts), "workspace", "patterns", "skills", "form", manifest.Name, families[0].ID, "--agent", "codex", "--draft-only")
	if err != nil || !strings.Contains(out, "# Deploy release") {
		t.Fatalf("draft-only form: %v\n%s", err, out)
	}
	assertWorkspaceSkillNotWritten(t, wsDir)
	out, err = execute(t, NewRootCommand(opts), "workspace", "patterns", "skills", "form", manifest.Name, families[0].ID, "--agent", "codex", "--yes")
	if err != nil || !strings.Contains(out, "formed skill") || !strings.Contains(out, "wrote ~/.agents/skills/deploy-release/SKILL.md") {
		t.Fatalf("install form: %v\n%s", err, out)
	}
	installed, err := os.ReadFile(workspaceSkillInstallPath(t))
	if err != nil || !strings.Contains(string(installed), "# Deploy release") {
func runRetrieve(ctx context.Context, cmd *cobra.Command, opts Options, query string, mode retrievalMode, limit int, branch string, ropts retrievalOptions, jsonOut, patterns bool, surface string) error {
	// Reject --limit <= 0 rather than silently defaulting, so a typo like
	// `--limit 0` is an explicit error (matching the rest of the CLI surface). The
	// MCP path passes a validated positive limit, so it's unaffected.
	if limit <= 0 {
		return fmt.Errorf("--limit must be greater than 0")
	}
	if len(ropts.Concepts) > 0 {
		if err := validateRetrievalLimit(limit); err != nil {
			return fmt.Errorf("--%s", err.Error())
		}
	}
	repoDir, brainDir, resolvedBranch, err := resolveFactsTarget(ctx, opts, agentSurfaceTarget(opts, nil), branch)
	if err != nil {
		return err
	}
	privacyPolicy, err := captureRetrievalPrivacyPolicy(brainDir)
	if err != nil {
		return err
	}
	if patterns {
		privacyPolicy.RequireDerivedClean = true
		if err := requirePrivacyDerivedRead(brainDir); err != nil {
			return err
		}
		if err := requirePatternCorpusAvailable(brainDir); err != nil {
			return err
		}
	}
	results, err := retrieveUnifiedWithOptions(repoDir, brainDir, resolvedBranch, query, limit, mode, ropts)
	if err != nil {
		return err
	}
	multiConcept := len(ropts.Concepts) > 0
	policyIdentityBeforeExtras := privacyPolicy.Identity
	factIDs := unifiedFactIDs(results)
	recordReceipt := func() {
		recordServedFacts(cmd.ErrOrStderr(), vitalityNow(opts), brainDir, resolvedBranch, surface,
			vitalityHead(ctx, opts.Runner, repoDir), query, factIDs)
	}
	// Discoverability only: pattern/theme pointers never enter the facts/history/
	// docs ranking — they are a separate, capped, opt-in section so default
	// retrieval quality is unchanged by construction.
	var related []relatedPatternRef
	if patterns {
		related, err = relatedPatternPointersChecked(brainDir, query, patternPointerCap)
		if err != nil {
			return err
		}
	}
	var abstractPreviews []sessionAbstractPreview
	var abstractPreviewsTruncated bool
	if ropts.IncludeAbstract {
		if ropts.Source != retrievalSourceConversation {
			return fmt.Errorf(`--include-abstract requires --source conversation (got %q)`, ropts.Source)
		}
		abstractPreviews, abstractPreviewsTruncated, err = abstractPreviewsForResults(brainDir, results)
		if err != nil {
			return err
		}
	}
	if !multiConcept {
		// Preserve the pre-multi-concept payload byte-for-byte, but buffer it so the shared
		// final privacy check runs after assembly and before the first write. The
		// 128 KiB response contract and proof rendering still belong only to
		// multi-concept coverage.
		if jsonOut {
			out := map[string]any{"query": query, "branch": resolvedBranch, "results": compactUnifiedResults(results, query)}
			if ropts.IncludeAbstract {
				out["abstract_previews"] = abstractPreviews
				out["abstract_previews_truncated"] = abstractPreviewsTruncated
			}
			hints := retrievalHintsForResults(repoDir, results, query)
			if len(hints.LikelyEditFiles) > 0 {
				out["likely_edit_files"] = hints.LikelyEditFiles
			}
			if len(hints.LikelyTestFiles) > 0 {
				out["likely_test_files"] = hints.LikelyTestFiles
			}
			if len(hints.ActionChecklist) > 0 {
				out["action_checklist"] = hints.ActionChecklist
			}
			if len(related) > 0 {
				out["related_patterns"] = related
			}
			if len(results) == 0 {
				if note := emptyResultBlindSpot(brainDir); note != "" {
					out["blind_spot"] = note
				}
			}
			serialized, err := jsonOutputBytes(out)
			if err != nil {
				return err
			}
			if err := writeRetrievalResponseBytes(cmd.OutOrStdout(), serialized, privacyPolicy); err != nil {
				return err
			}
			if len(factIDs) > 0 {
				recordReceipt()
			}
			return nil
		}
		var rendered bytes.Buffer
		if err := writeTextToWriter(&rendered, func(out io.Writer) {
			if len(results) == 0 {
				fmt.Fprintf(out, "no results for %q\n", query)
				if note := emptyResultBlindSpot(brainDir); note != "" {
					fmt.Fprintln(out, note)
				}
			}
			hints := retrievalHintsForResults(repoDir, results, query)
			for _, file := range hints.LikelyEditFiles {
				fmt.Fprintf(out, "edit_file %s\n", file)
			}
			for _, file := range hints.LikelyTestFiles {
				fmt.Fprintf(out, "test_file %s\n", file)
			}
			for _, action := range hints.ActionChecklist {
				fmt.Fprintf(out, "action %s %s: %s\n", action.File, action.Symbol, action.Action)
			}
			for _, result := range results {
				ex := truncateString(strings.Join(strings.Fields(result.Text), " "), 200)
				label := result.Source
				if result.VerificationRequired {
					label += " verify"
				}
				fmt.Fprintf(out, "[%s] %s  %s\n    %s\n", label, result.ID, unifiedResultLocation(result), ex)
				printRetrievalCaveats(out, result)
			}
			for _, pattern := range related {
				fmt.Fprintf(out, "related [%s] %s  %s\n", pattern.Type, pattern.ID, pattern.Title)
			}
			for _, preview := range abstractPreviews {
				text := ""
				if preview.Overview != nil {
					text = "  " + strings.Join(strings.Fields(preview.Overview.Text), " ")
				}
				fmt.Fprintf(out, "abstract [%s] %s%s\n", preview.AbstractStatus, preview.SessionRef, text)
				if preview.AbstractIssue != "" {
					fmt.Fprintf(out, "  automatic enqueue issue: %s\n", preview.AbstractIssue)
				}
			}
			if abstractPreviewsTruncated {
				fmt.Fprintln(out, "abstract previews truncated")
			}
		}); err != nil {
			return err
		}
		if err := writeRetrievalResponseBytes(cmd.OutOrStdout(), rendered.Bytes(), privacyPolicy); err != nil {
			return err
		}
		if len(factIDs) > 0 {
			recordReceipt()
		}
		return nil
	}
	// Ranking may be slow enough for a concurrent exclusion to land after its
	// first guard snapshot. Revalidate immediately before transport assembly;
	// no JSON, text, or MCP bytes are emitted before this check succeeds.
	results, policyAfter, err := revalidateRetrievalResponsePrivacy(brainDir, results)
	if err != nil {
		return err
	}
	if policyAfter != policyIdentityBeforeExtras {
		// Optional derived material was read under a superseded privacy policy.
		// Rows were freshly revalidated above; discard the stale extras instead
		// of allowing a completed fast cleanup to make them look current.
		related = nil
		abstractPreviews = nil
		abstractPreviewsTruncated = true
	}
	extras := retrievalTransportExtras{
		AbstractPreviews:          abstractPreviews,
		AbstractPreviewsTruncated: abstractPreviewsTruncated,
		Hints:                     retrievalHintsForResults(repoDir, results, query),
		Related:                   related,
	}
	if len(results) == 0 {
		extras.BlindSpot = emptyResultBlindSpot(brainDir)
	}
	if jsonOut {
		// Preserve the established JSON `text` field on both CLI and MCP
		// surfaces. Excerpt is additive; existing consumers must not be forced to
		// switch to a second brain_get round trip.
		out, err := boundedRetrievalJSONPayload(ctx, query, resolvedBranch, results, extras, surface)
		if err != nil {
			return err
		}
		serialized, err := jsonOutputBytes(out)
		if err != nil {
			return err
		}
		if err := writeRetrievalResponseBytes(cmd.OutOrStdout(), serialized, retrievalPrivacyPolicy{BrainDir: brainDir, Identity: policyAfter}); err != nil {
			return err
		}
		if len(factIDs) > 0 {
			recordReceipt()
		}
		return nil
	}
	text, err := boundedSingleRepoRetrievalText(query, results, extras)
	if err != nil {
		return err
	}
	if err := writeRetrievalResponseBytes(cmd.OutOrStdout(), text, retrievalPrivacyPolicy{BrainDir: brainDir, Identity: policyAfter}); err != nil {
		return err
	}
	if len(factIDs) > 0 {
		recordReceipt()
	}
	return nil
}

