package cli

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"strings"
	"testing"
	"time"
)

// seedPromotableMember builds a member corpus whose (intentSig, heads) task is
// promotable (12 corroborated successes + noise), so it surfaces as a member
// task candidate for the workspace judgment layer.
func seedPromotableMember(t *testing.T, brainDir, repoKey, intentSig string, heads ...string) {
	t.Helper()
	path, err := prepareBrainRelativeSQLiteFile(brainDir, patternCorpusPath)
	if err != nil {
		t.Fatal(err)
	}
	db, err := sql.Open(sqliteDriverName, path)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	for _, s := range patternCorpusSchema {
		if _, err := db.Exec(s); err != nil {
			t.Fatalf("schema: %v", err)
		}
	}
	now := time.Now()
	for i := 0; i < 12; i++ {
		id := fmt.Sprintf("%s:ok%d", intentSig, i)
		insertCorpusEpisode(t, db, id, intentSig, "success", len(heads), now)
		insertCorpusShape(t, db, id, heads...)
		db.Exec(`INSERT INTO episode_facts (episode_id, fact_id, kind, paths, weight) VALUES (?,?,?,?,2)`,
			id, "fact:"+intentSig, "architecture", "ops/x.go")
	}
	for i := 0; i < 120; i++ {
		id := fmt.Sprintf("%s:noise%d", intentSig, i)
		insertCorpusEpisode(t, db, id, "other:thing", "neutral", 2, now)
		insertCorpusShape(t, db, id, "ls", "cat")
	}
	if err := buildPatternCandidates(db, repoKey, now); err != nil {
		t.Fatal(err)
	}
}

// releaseGroupingAgent groups repos whose task intent mentions "release" into one
// cross-repo family (with each repo's actual commands); it rejects generic git.
func releaseGroupingAgent(t *testing.T) distillAgentRunner {
	return func(ctx context.Context, dir string, args []string, input []byte, timeout time.Duration) (string, error) {
		var payload struct {
			Repos map[string][]map[string]any `json:"repos"`
		}
		if err := json.Unmarshal(input, &payload); err != nil {
			t.Fatalf("family proposal input not JSON: %v\n%s", err, input)
		}
		var perRepo []map[string]any
		generic := true
		for repo, tasks := range payload.Repos {
			for _, tk := range tasks {
				intent := fmt.Sprint(tk["intent"])
				if strings.Contains(intent, "release") {
					perRepo = append(perRepo, map[string]any{"repo_key": repo, "commands": tk["commands"]})
					generic = false
				}
			}
		}
		verdict := "accepted"
		if generic { // only generic git tasks present
			verdict = "rejected"
		}
		resp := map[string]any{"families": []map[string]any{{
			"title":           "release the build",
			"trigger":         "shipping a release",
			"purpose":         "build then publish a release",
			"common_workflow": []string{"build", "publish release"},
			"per_repo":        perRepo,
			"verdict":         verdict,
		}}}
// newWorkspaceRetrieveCommand mirrors the top-level search/vsearch/query verbs
// (retrieve_cmd.go) as a per-member fan-out: each repo's brain is ranked
// independently and results stay grouped by repo — scores from different brains'
// indexes are not comparable, so there is no cross-repo fusion.
func newWorkspaceRetrieveCommand(opts Options, use string, mode retrievalMode, short string) *cobra.Command {
	var selection querySelection
	retrieveOpts := workspaceRetrieveOptions{limit: 10}
	cmd := &cobra.Command{
		Use:   use + " <workspace> <query>",
		Short: short,
		Args:  cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			selectedMode, err := selection.mode(mode)
			if err != nil {
				return err
			}
			return runWorkspaceRetrieve(cmd, opts, retrieveOpts, selectedMode, args[0], args[1])
		},
	}
	configureQueryCommand(cmd, use, &selection, 1)
	cmd.Flags().IntVar(&retrieveOpts.limit, "limit", 10, "Maximum results per repo")
	cmd.Flags().StringVar(&retrieveOpts.branch, "branch", "", "Branch for facts in every repo (default: each repo's distill default)")
	cmd.Flags().BoolVar(&retrieveOpts.json, "json", false, "Emit machine-readable JSON")
	cmd.Flags().StringVar(&retrieveOpts.source, "source", "", "Restrict retrieval to one source per repo: all, fact, history, conversation, or doc (conversation is experimental opt-in)")
	cmd.Flags().StringVar(&retrieveOpts.after, "after", "", "Conversation source only: sessions at or after this time (RFC3339 or YYYY-MM-DD)")
	cmd.Flags().StringVar(&retrieveOpts.before, "before", "", "Conversation source only: sessions before this time (RFC3339 or YYYY-MM-DD)")
	cmd.Flags().StringVar(&retrieveOpts.session, "session", "", "Conversation source only: exchanges from this session id")
	cmd.Flags().StringVar(&retrieveOpts.agent, "agent", "", "Conversation source only: exchanges captured by this agent/harness")
	cmd.Flags().StringArrayVar(&retrieveOpts.concepts, "concept", nil, "Conversation source only: additional concept (repeatable, up to 4); each member repo's sessions must match the query AND every concept")
	cmd.Flags().BoolVar(&retrieveOpts.includeAbstract, "include-abstract", false, "Conversation source only: include bounded evidence-linked session previews per member repo")
	return cmd
}

