const midtaskTasksPerSession = 3
func newHistoryEvalCommand(opts Options) *cobra.Command {
	var (
		tasksFile string
		branch    string
		k         int
		arm       string
		cutoff    float64
		jsonOut   bool
	)
	cmd := &cobra.Command{
		Use:   "history-eval --tasks <file>",
		Short: "Measure history-retrieval quality (tokens, precision, useful-records-per-1k) over held-out tasks",
		Long: `history-eval runs a labeled task set (from history-eval-gen) through one history
retrieval arm and reports the same metrics as 'facts eval' — surfaced records,
estimated tokens, precision, recall, useful-per-1k — so 'facts eval-compare'
works on the summaries unchanged.

Arms:
  substring  the pre-BM25 coverage-gate scorer (the 1a baseline)
  bm25       the shipped FTS5 ranker; --cutoff sweeps its relevance cutoff
  fused      bm25 + semantic (RRF k=60) over record summaries — the prospective
             arm the alignment plan wants measured. Uses the configured
             embedder (ENTIRE_BRAIN_EMBEDDER=ollama selects EmbeddingGemma);
             every index record is embedded once per run, so the first fused
             run over a large brain with a server-backed embedder is slow.`,
		Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			if strings.TrimSpace(tasksFile) == "" {
				return fmt.Errorf("--tasks <file> is required")
			}
			tasks, err := loadEvalTasks(tasksFile)
			if err != nil {
				return err
			}
			_, brainDir, _, err := resolveFactsTarget(cmd.Context(), opts, agentSurfaceTarget(opts, nil), branch)
			if err != nil {
				return err
			}
			manifest, err := loadBrainManifest(brainDir)
			if err != nil {
				return err
			}
			if manifest.Sources == nil {
				return fmt.Errorf("brain has no sources; run `entire brain refresh` first")
			}
			index, err := loadBrainHistoryIndex(brainDir, manifest.Sources.History)
			if err != nil {
				return err
			}
			armFn, err := selectHistoryEvalArm(arm, brainDir, index, cutoff)
			if err != nil {
				return err
			}
			results, err := runHistoryEval(tasks, k, armFn)
			if err != nil {
				return err
			}
			summary := summarizeEval(results)
			summary.Arm = arm
			if jsonOut {
				return writeJSON(cmd, summary)
			}
			printEvalSummary(cmd, summary)
			return nil
		},
	}
	cmd.Flags().StringVar(&tasksFile, "tasks", "", "Path to the held-out task set (JSON array, from history-eval-gen)")
	cmd.Flags().StringVar(&branch, "branch", "", "Brain branch context (default: current branch)")
	cmd.Flags().IntVar(&k, "k", 10, "Records to retrieve per task")
	cmd.Flags().StringVar(&arm, "arm", "bm25", "Retrieval arm: substring | bm25 | fused")
	cmd.Flags().Float64Var(&cutoff, "cutoff", historyFTSRelevanceCutoff, "BM25 relevance cutoff (fraction of the top score) for the bm25/fused arms")
	cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit the summary as JSON")
	return cmd
}

func selectHistoryEvalArm(arm, brainDir string, index historyIndex, cutoff float64) (historyEvalArm, error) {
	switch arm {
	case "substring":
		return func(query string, k int) ([]historyRecord, error) {
			return rankHistoryRecords(index, "history", query, k), nil
		}, nil
	case "bm25":
		return func(query string, k int) ([]historyRecord, error) {
			// A query with no usable FTS terms (e.g. all stopwords: "fix") is a
			// deterministic honest empty — the same as the fused arm's lexical
			// side — not a harness failure. Only a real index fault errors.
			if historyFTSMatchExpr(query) == "" {
				return nil, nil
			}
			scored, ok := rankHistoryViaFTSCutoff(brainDir, index, "history", query, k, cutoff)
			if !ok {
				return nil, fmt.Errorf("bm25 arm unavailable for query %q (FTS index failed to build or query failed)", query)
			}
			return historyRecordsOf(scored), nil
		}, nil
	case "fused":
		e := defaultEmbedder()
		if e == nil {
			return nil, fmt.Errorf("--arm fused requested but the embedding backend is unavailable")
		}
		f := newHistoryFusedRanker(brainDir, index, e, cutoff)
		return f.rank, nil
	default:
		return nil, fmt.Errorf("unknown arm %q (substring | bm25 | fused)", arm)
	}
}

func historyRecordsOf(scored []scoredHistoryRecord) []historyRecord {
	out := make([]historyRecord, 0, len(scored))
	for _, s := range scored {
		out = append(out, s.Record)
	}
	return out
}

func runHistoryEval(tasks []evalTask, defaultK int, arm historyEvalArm) ([]evalTaskResult, error) {
	results := make([]evalTaskResult, 0, len(tasks))
	for _, task := range tasks {
		k := task.K
		if k <= 0 {
			k = defaultK
		}
		surfaced, err := arm(task.Task, k)
		if err != nil {
			return nil, fmt.Errorf("task %s: %w", task.ID, err)
		}
		relevant := make(map[string]struct{}, len(task.Relevant))
		for _, id := range task.Relevant {
			relevant[id] = struct{}{}
		}
		res := historyEvalMetrics(surfaced, relevant, len(relevant))
		res.ID, res.Task, res.QueryType, res.Labeled = task.ID, task.Task, task.QueryType, len(task.Relevant) > 0
		if res.Labeled {
			// Provenance labels, declared as such: eval-compare pairs two
			// history runs as same-truth, and EvidenceBasis stays proxy (the
			// labels are silver, never proof-grade).
			res.RelevanceSource = evalRelevanceExplicitLabel
			res.LabelSource = normalizedEvalLabelSource(task)
		}
		results = append(results, res)
	}
	return results, nil
}

// historyEvalMetrics mirrors evalMetrics over history records. The token
// estimate covers what an agent actually loads per surfaced record: the
// summary (already truncated to 700 chars at index time) plus its provenance
// path.
func historyEvalMetrics(surfaced []historyRecord, relevant map[string]struct{}, totalRelevant int) evalTaskResult {
	chars := 0
	for _, r := range surfaced {
		chars += len(r.Summary) + len(r.Path) + 4 // small per-record framing
	}
	res := evalTaskResult{Surfaced: len(surfaced), Tokens: (chars + 3) / 4}
	for _, r := range surfaced {
		if _, ok := relevant[r.ID]; ok {
			res.RelevantSurfaced++
		}
	}
	if res.Surfaced > 0 {
		res.Precision = float64(res.RelevantSurfaced) / float64(res.Surfaced)
	}
	if totalRelevant > 0 {
		res.Recall = float64(res.RelevantSurfaced) / float64(totalRelevant)
	}
	if res.Tokens > 0 {
		res.UsefulPer1k = float64(res.RelevantSurfaced) / (float64(res.Tokens) / 1000.0)
	}
	return res
}

// --- fused arm (BM25 + semantic RRF) ----------------------------------------

// historyFusedRanker is the prospective history semantic arm: RRF fusion of
func newFactsEvalCompareCommand(opts Options) *cobra.Command {
	var (
		aPath                      string
		bPath                      string
		alpha                      float64
		jsonOut                    bool
		allowProxyComparison       bool
		allowMissingTasks          bool
		allowTaskHashMismatch      bool
		allowBrainManifestMismatch bool
	)
	cmd := &cobra.Command{
		Use:   "eval-compare --a <A.json> --b <B.json>",
		Short: "Paired A/B comparison of two eval runs with a t-test and Holm correction",
		Long: `eval-compare reads two 'facts eval --json' summaries over the SAME tasks (two
retrieval configs, e.g. base vs --expand) and reports, per metric, the paired
mean delta, a two-sided Student-t p-value, Cohen's d, and a Holm-Bonferroni
family-wise significance verdict. Relevance metrics require comparable
human/judge_refined proof labels unless --allow-proxy-comparison is explicit.
Task IDs must match exactly. Non-empty task-file hashes and brain manifest
hashes must match unless the corresponding override is explicit; missing hashes
leave the comparison usable for smoke but disable release_claimable metrics. Use
it to report a lift honestly instead of eyeballing two means.`,
		Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			if aPath == "" || bPath == "" {
				return fmt.Errorf("--a and --b are required")
			}
			a, err := loadEvalSummary(aPath)
			if err != nil {
				return err
			}
			b, err := loadEvalSummary(bPath)
			if err != nil {
				return err
			}
			compareOpts := evalCompareOptions{
				AllowProxyComparison:       allowProxyComparison,
				AllowMissingTasks:          allowMissingTasks,
				AllowTaskHashMismatch:      allowTaskHashMismatch,
				AllowBrainManifestMismatch: allowBrainManifestMismatch,
			}
			comparisons, n, missingFromA, missingFromB, err := compareEvalSummariesInternalWithOptions(a, b, alpha, compareOpts)
			if err != nil {
				return err
			}
			if n == 0 {
				return fmt.Errorf("the two runs share no task ids to compare")
			}
			releasePairingReady := evalSummariesReleasePairingReadyWithOptions(a, b, compareOpts, missingFromA, missingFromB)
			releasePairingNote := evalCompareReleasePairingNote(a, b, compareOpts, missingFromA, missingFromB)
			if jsonOut {
				return writeJSON(cmd, map[string]any{"n": n, "alpha": alpha, "a_retriever": a.Retriever, "b_retriever": b.Retriever, "a_tasks_sha256": evalSummaryTasksSHA256(a), "b_tasks_sha256": evalSummaryTasksSHA256(b), "a_brain_manifest_sha256": evalSummaryBrainManifestSHA256(a), "b_brain_manifest_sha256": evalSummaryBrainManifestSHA256(b), "release_pairing_ready": releasePairingReady, "release_claimable": evalComparisonsReleaseClaimable(comparisons), "release_pairing_note": releasePairingNote, "allow_proxy_comparison": allowProxyComparison, "allow_missing_tasks": allowMissingTasks, "allow_task_hash_mismatch": allowTaskHashMismatch, "allow_brain_manifest_mismatch": allowBrainManifestMismatch, "missing_from_a": missingFromA, "missing_from_b": missingFromB, "metrics": comparisons})
			}
			out := cmd.OutOrStdout()
			fmt.Fprintf(out, "paired A/B over %d shared tasks (Holm-corrected at alpha=%.2f)\n", n, alpha)
			if a.Retriever != "" || b.Retriever != "" {
				fmt.Fprintf(out, "A=%s B=%s\n", valueOrUnset(a.Retriever), valueOrUnset(b.Retriever))
			}
			if allowProxyComparison {
				fmt.Fprintln(out, "warning: relevance metrics may mix explicit labels, source-match proxies, and/or judge labels")
			}
			if allowMissingTasks && (len(missingFromA) > 0 || len(missingFromB) > 0) {
				fmt.Fprintf(out, "warning: comparing shared ids only; missing_from_a=%d missing_from_b=%d\n", len(missingFromA), len(missingFromB))
			}
			if allowTaskHashMismatch {
				fmt.Fprintln(out, "warning: task file hashes differ or were explicitly ignored; release_claimable metrics are disabled")
			}
			if allowBrainManifestMismatch {
				fmt.Fprintln(out, "warning: brain manifest hashes differ or were explicitly ignored; release_claimable metrics are disabled")
			}
			if releasePairingNote != "" {
				fmt.Fprintln(out, releasePairingNote)
			}
			fmt.Fprintf(out, "%-14s %-14s %9s %9s %9s %8s %7s %8s %-6s %s\n", "metric", "evidence", "A", "B", "delta", "t", "p", "cohen_d", "winner", "claim")
			for _, c := range comparisons {
				fmt.Fprintf(out, "%-14s %-14s %9.3f %9.3f %+9.3f %8.2f %7.3f %8.2f %-6s %s\n",
					c.Metric, c.EvidenceBasis, c.MeanA, c.MeanB, c.Delta, c.T, c.P, c.CohenD, c.Winner, c.Claim)
			}
			if n < 12 {
				fmt.Fprintf(out, "note: n=%d is small — treat as directional; significance is underpowered.\n", n)
			}
			return nil
		},
	}
	cmd.Flags().StringVar(&aPath, "a", "", "Baseline eval summary JSON (facts eval --json)")
	cmd.Flags().StringVar(&bPath, "b", "", "Comparison eval summary JSON")
	cmd.Flags().Float64Var(&alpha, "alpha", 0.05, "Family-wise significance level for Holm correction")
	cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit the comparison as JSON")
	cmd.Flags().BoolVar(&allowProxyComparison, "allow-proxy-comparison", false, "Allow relevance metrics to compare runs with different relevance sources")
	cmd.Flags().BoolVar(&allowMissingTasks, "allow-missing-tasks", false, "Compare only shared task ids when eval runs have missing tasks")
	cmd.Flags().BoolVar(&allowTaskHashMismatch, "allow-task-hash-mismatch", false, "Allow comparison when non-empty eval run_config.tasks_sha256 values differ")
	cmd.Flags().BoolVar(&allowBrainManifestMismatch, "allow-brain-manifest-mismatch", false, "Allow comparison when non-empty eval run_config.brain_manifest_sha256 values differ")
	return cmd
}

